insert into CHB_ASSETS_ELEMENTS_SUB (REGIST_SEQNO, STATUS_BATCH, ASSET_ID, ASSET_NAME, INFORMATION_ASSETS_ID, ASSET_FLAG, FINANCIER_NAME, INDUSTRY_ID, CCY, HOLD_AMOUNT, ON_PASSAGE_AMT, HOLD_QTY_AMOUNT, BONDSMAN, FUNDS_USE_REMARK, PAYMENT_REMARK, ORG_ID, BANK_MARK, DATE_STATUS, GROUP_ID, CREATE_USER, ORG_CODE, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) select A.* from (
select #{item.registSeqno,jdbcType=VARCHAR} AS REGIST_SEQNO, #{item.statusBatch,jdbcType=VARCHAR} AS STATUS_BATCH, #{item.assetId,jdbcType=VARCHAR} AS ASSET_ID, #{item.assetName,jdbcType=VARCHAR} AS ASSET_NAME, #{item.informationAssetsId,jdbcType=VARCHAR} AS INFORMATION_ASSETS_ID, #{item.assetFlag,jdbcType=VARCHAR} AS ASSET_FLAG, #{item.financierName,jdbcType=VARCHAR} AS FINANCIER_NAME, #{item.industryId,jdbcType=VARCHAR} AS INDUSTRY_ID, #{item.ccy,jdbcType=VARCHAR} AS CCY, #{item.holdAmount,jdbcType=DECIMAL} AS HOLD_AMOUNT, #{item.onPassageAmt,jdbcType=DECIMAL} AS ON_PASSAGE_AMT, #{item.holdQtyAmount,jdbcType=DECIMAL} AS HOLD_QTY_AMOUNT, #{item.bondsman,jdbcType=VARCHAR} AS BONDSMAN, #{item.fundsUseRemark,jdbcType=VARCHAR} AS FUNDS_USE_REMARK, #{item.paymentRemark,jdbcType=VARCHAR} AS PAYMENT_REMARK, #{item.orgId,jdbcType=VARCHAR} AS ORG_ID, #{item.bankMark,jdbcType=VARCHAR} AS BANK_MARK, #{item.dateStatus,jdbcType=DATE} AS DATE_STATUS, #{item.groupId,jdbcType=VARCHAR} AS GROUP_ID, #{item.createUser,jdbcType=VARCHAR} AS CREATE_USER, #{item.orgCode,jdbcType=VARCHAR} AS ORG_CODE, #{item.createDept,jdbcType=VARCHAR} AS CREATE_DEPT, now() AS CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} AS UPDATE_USER, now() AS UPDATE_TIME from dual
) A
